import {FormEvent,useEffect,useState} from "react";
import {AlertTriangle,Archive,ArrowLeft,Check,CheckCircle2,ChevronRight,Clock3,Download,FolderOpen,History,Inbox,LayoutDashboard,LoaderCircle,LockKeyhole,Mail,RefreshCw,RotateCcw,Search,ShieldCheck,Sparkles,Trash2,Upload,UserRound,Users,X} from "lucide-react";
import {designerStore,type DesignerSnapshot} from "../designer-store";
import {DesignerCaseStatus,agentPhotoSummary,groupAgentsByTeam,isPhotoReminderEligible,matchesDesignerSearch,overviewCounts,photoReminderRecipient,sanitiseApprovedFilename,sortAgentsByPhotoState,type AgentPhotoState,type DesignerAction,type DesignerAgent,type DesignerAsset,type DesignerEnhancement,type DesignerSubmission,type PhotoReminder} from "../designer-records";
