type Section="overview"|"queue"|"assets"|"directory"|"history";
const pendingStatuses=new Set([DesignerCaseStatus.PENDING_DESIGNER_APPROVAL,DesignerCaseStatus.AI_ENHANCED_REVIEW,DesignerCaseStatus.DESIGNER_REVIEW_REQUESTED]);
const empty:DesignerSnapshot={submissions:[],enhancements:[],reviews:[],assets:[],events:[],agents:[],reminders:[]};
