 const nav=[{id:"overview" as const,label:"Overview",icon:LayoutDashboard,count:0},{id:"queue" as const,label:"Review queue",icon:Inbox,count:counts.pending},{id:"assets" as const,label:"Photo library",icon:FolderOpen,count:images.length},{id:"directory" as const,label:"Agent directory",icon:Users,count:0},{id:"history" as const,label:"History",icon:History,count:0}];
