 const summaryOf=(agent:DesignerAgent)=>agentPhotoSummary(agent.agentId,snapshot.submissions,snapshot.assets,agent),teams=[...new Set(agents.map(agent=>agent.teamName).filter(Boolean))].sort(),filtered=agents.filter(agent=>(photoFilter==="all"||summaryOf(agent).state===photoFilter)&&(teamFilter==="all"||agent.teamName===teamFilter)),ordered=sort==="status"?sortAgentsByPhotoState(filtered,snapshot.submissions,snapshot.assets):[...filtered].sort((a,b)=>sort==="images"?summaryOf(b).images-summaryOf(a).images||a.name.localeCompare(b.name):a.name.localeCompare(b.name)),selectedAgents=agents.filter(agent=>selectedIds.has(agent.agentId)),downloadable=selectedAgents.map(agent=>currentDownloadableAsset(agent,snapshot.assets)).filter(item=>item!==null),reminderEligible=emailTestMode&&!testRecipient?[]:selectedAgents.filter(agent=>isPhotoReminderEligible(agent,summaryOf(agent),emailTestMode?testRecipient:"")),optedOutCount=selectedAgents.filter(agent=>summaryOf(agent).state==="opted_out").length,allVisibleSelected=Boolean(ordered.length)&&ordered.every(agent=>selectedIds.has(agent.agentId)),lastReminder=(agentId:string)=>snapshot.reminders.find(item=>item.agentId===agentId),recentReminderCount=reminderEligible.filter(agent=>{const last=lastReminder(agent.agentId);return last&&now-new Date(last.sentAt).getTime()<24*60*60*1000}).length;
 const toggle=(id:string)=>setSelectedIds(current=>{const next=new Set(current);if(next.has(id))next.delete(id);else next.add(id);return next}),selectAll=()=>setSelectedIds(current=>{const next=new Set(current);if(allVisibleSelected)ordered.forEach(agent=>next.delete(agent.agentId));else ordered.forEach(agent=>next.add(agent.agentId));return next}),clear=()=>setSelectedIds(new Set());
 const bulkDownloadSelectedAssets=async()=>{const files=[] as {name:string;data:Uint8Array}[];for(const item of downloadable){const blob=await designerStore().image(item.imageId);if(!blob)continue;const extension=blob.type.includes("jpeg")?"jpg":"png",name=sanitiseApprovedFilename(item.agent.name,item.agent.agentId,extension,item.asset.sourceType);files.push({name,data:new Uint8Array(await blob.arrayBuffer())})}if(!files.length)return;if(files.length===1){const blob=new Blob([files[0].data]),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download=files[0].name;link.click();window.setTimeout(()=>URL.revokeObjectURL(url),1000)}else{const zip=createPhotoZip(files),url=URL.createObjectURL(zip),link=document.createElement("a");link.href=url;link.download=`ProfileLabAI_Approved_Photos_${files.length}.zip`;link.click();window.setTimeout(()=>URL.revokeObjectURL(url),1000)}setDownloadOpen(false)};
