function MockMailbox({reminders,excluded}:{reminders:PhotoReminder[];excluded:{label:string;count:number}[]}){const smtpDelivered=reminders.filter(item=>item.deliveryStatus==="SMTP_DELIVERED").length,failed=reminders.filter(item=>item.deliveryStatus==="FAILED").length,actualRecipient=reminders[0]?.actualRecipientEmail;return <div className="mock-mailbox"><div>{failed&&!smtpDelivered?<AlertTriangle size={20}/>:<CheckCircle2 size={20}/>}<span><h3>{smtpDelivered?"Test Reminders Sent":failed?"Test Reminder Delivery Failed":"Mock Reminders Prepared"}</h3><b>{smtpDelivered?`${smtpDelivered} test email${smtpDelivered===1?"":"s"} successfully sent${failed?` · ${failed} failed`:""}`:failed?`${failed} reminder${failed===1?"":"s"} failed`:`${reminders.length} reminder${reminders.length===1?"":"s"} added to the mock mailbox`}</b><small>{smtpDelivered?`Actual delivery inbox: ${actualRecipient}`:failed?"Check the SMTP bridge terminal and credentials, then retry.":"Delivery status: MOCK_DELIVERED · no network request was made"}</small></span></div>{excluded.length?<div className="bulk-cooldown"><AlertTriangle size={17}/>{excluded.reduce((sum,item)=>sum+item.count,0)} excluded · {excluded.map(item=>`${item.count} ${item.label}`).join(" · ")}</div>:null}{reminders.map(reminder=><article key={reminder.reminderId}><span><b>{reminder.agentName}</b><small>{reminder.actualRecipientEmail} · {reminder.deliveryStatus}</small></span><EmailPreview agent={{agentId:reminder.agentId,name:reminder.agentName,teamName:"",ren:"",avatarUrl:"",email:reminder.intendedRecipientEmail}} reminder={reminder}/></article>)}</div>}

