function AgentStateBadge({summary}:{summary:ReturnType<typeof agentPhotoSummary>}){return <span className={`designer-agent-state ${summary.state}`}><i/>{summary.state==="pending"?`${summary.pending} pending`:summary.state==="approved"?`${summary.approved} approved`:summary.state==="retake"?"Retake required":summary.state==="reupload"?"Re-upload required":summary.state==="opted_out"?"Opted Out":summary.state==="has_images"?`${summary.images} image${summary.images===1?"":"s"}`:"Photo required"}</span>}
function HistoryFeed({snapshot}:{snapshot:DesignerSnapshot}){return <section><PageTitle eyebrow="AUDIT TRAIL" title="Decision history" copy="Every submission, approval and asset handoff stays attributable."/>{snapshot.events.length?<div className="designer-history">{snapshot.events.map(event=><article key={event.eventId}><span><History size={16}/></span><div><b>{event.action}</b><p>{agentName(snapshot,event.agentId)} · {event.agentId}</p><small>{dateTime(event.at)}{event.actor?` · ${event.actor}`:""}</small></div><code>{event.refId}</code></article>)}</div>:<div className="designer-first-run compact"><History size={29}/><h2>No history yet</h2><p>Designer and kiosk events will appear here.</p></div>}</section>}

function libraryImages(snapshot:DesignerSnapshot){const images=new Map<string,LibraryImage>(),assetByImage=new Map(snapshot.assets.map(asset=>[`${asset.agentId}:${asset.imageId}`,asset]));for(const submission of snapshot.submissions){const asset=assetByImage.get(`${submission.agentId}:${submission.imageId}`),status=asset?"approved":pendingStatuses.has(submission.status)?"pending":submission.status===DesignerCaseStatus.RETAKE_REQUIRED?"retake":submission.status===DesignerCaseStatus.REUPLOAD_REQUIRED?"reupload":"uploaded";images.set(`${submission.agentId}:${submission.imageId}`,{key:`submission-${submission.submissionId}`,agentId:submission.agentId,imageId:submission.imageId,sourceType:asset?.sourceType??"original",status,score:asset?.marketingReadiness??submission.marketingReadiness,at:asset?.approvedAt??submission.createdAt,asset})}for(const enhancement of snapshot.enhancements){const asset=assetByImage.get(`${enhancement.agentId}:${enhancement.imageId}`);images.set(`${enhancement.agentId}:${enhancement.imageId}`,{key:`enhancement-${enhancement.enhancementId}`,agentId:enhancement.agentId,imageId:enhancement.imageId,sourceType:asset?.sourceType??"ai_enhanced",status:asset?"approved":pendingStatuses.has(enhancement.status)?"pending":"uploaded",score:asset?.marketingReadiness??enhancement.enhancedMarketingReadiness,at:asset?.approvedAt??enhancement.createdAt,asset})}for(const asset of snapshot.assets){const key=`${asset.agentId}:${asset.imageId}`,current=images.get(key);images.set(key,current?{...current,status:"approved",sourceType:asset.sourceType,score:asset.marketingReadiness??current.score,at:asset.approvedAt,asset}:{key:`asset-${asset.assetId}`,agentId:asset.agentId,imageId:asset.imageId,sourceType:asset.sourceType,status:"approved",score:asset.marketingReadiness??0,at:asset.approvedAt,asset})}return [...images.values()].sort((a,b)=>b.at.localeCompare(a.at))}
function imageGroups(snapshot:DesignerSnapshot,images:LibraryImage[]){const agentMap=new Map(snapshot.agents.map(agent=>[agent.agentId,agent]));for(const submission of snapshot.submissions)if(!agentMap.has(submission.agentId))agentMap.set(submission.agentId,{agentId:submission.agentId,name:submission.agentName,teamName:submission.teamNameAtSubmission||"Unassigned",ren:"",avatarUrl:""});const imageAgents=[...agentMap.values()].filter(agent=>images.some(image=>image.agentId===agent.agentId)),teams=groupAgentsByTeam(imageAgents);return teams.map(group=>({team:group.team,imageCount:group.agents.reduce((total,agent)=>total+images.filter(image=>image.agentId===agent.agentId).length,0),agents:group.agents.map(agent=>({agent,images:images.filter(image=>image.agentId===agent.agentId)}))}))}
function mergeAgents(local:DesignerAgent[],remote:DesignerAgent[]){const merged=new Map<string,DesignerAgent>();[...remote,...local].forEach(agent=>merged.set(agent.agentId,agent));return [...merged.values()]}
function agentName(snapshot:DesignerSnapshot,id:string){return snapshot.agents.find(agent=>agent.agentId===id)?.name??snapshot.submissions.find(item=>item.agentId===id)?.agentName??id}
function categoryLabel(name:string){return{photoQuality:"Photo quality",bodyCrop:"Body & crop",faceVisibility:"Face visibility",backgroundEditability:"Background & editability"}[name]??name}
function statusLabel(status:string){return status.toLowerCase().replaceAll("_"," ").replace(/\b\w/g,character=>character.toUpperCase())}
function libraryStatusLabel(status:LibraryImage["status"]){return{pending:"Pending approval",approved:"Approved",retake:"Retake required",reupload:"Re-upload required",uploaded:"Uploaded"}[status]}
function actionLabel(action:DesignerAction,enhancement?:DesignerEnhancement){return{approve_original:"Approve original photo",approve_enhanced:"Approve AI-enhanced portrait",reject_enhancement:"Reject AI enhancement",retake:"Request a new photo",reupload:"Request a larger file",keep_review:`Keep ${enhancement?"enhanced ":""}case in review`}[action]}
